<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<meta name="description" content="Piet Mondrian's Composition with Red, Blue and Yellow (1930): painter, year, movement, and why the work matters.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>
  :root {
    --red: #d40920;
    --blue: #003087;
    --yellow: #f5c518;
    --black: #111111;
    --white: #ffffff;
    --grey: #e8e8e8;
    --line: 10px;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    font-family: 'Archivo', 'Helvetica Neue', Helvetica, Arial, sans-serif;
    background: var(--white);
    color: var(--black);
    line-height: 1.5;
  }

  /* ===== Mondrian grid canvas (decorative, top) ===== */
  .canvas {
    display: grid;
    grid-template-columns: 1.4fr 1fr 0.6fr;
    grid-template-rows: 1fr 1fr 0.8fr;
    gap: var(--line);
    background: var(--black);
    min-height: 62vh;
    padding: var(--line);
  }
  .canvas > div { background: var(--white); }
  .canvas .c-red    { background: var(--red); grid-column: 3; grid-row: 1; }
  .canvas .c-blue   { background: var(--blue); grid-column: 1; grid-row: 3; }
  .canvas .c-yellow { background: var(--yellow); grid-column: 3; grid-row: 3; }
  .c-title  { grid-column: 1 / 3; grid-row: 1 / 3; padding: clamp(24px, 5vw, 56px); display: flex; flex-direction: column; justify-content: center; }
  .c-title h1 {
    font-weight: 900;
    font-size: clamp(28px, 4.6vw, 60px);
    line-height: 1.05;
    letter-spacing: -0.02em;
    text-transform: uppercase;
  }
  .c-title .sub {
    margin-top: 16px;
    font-weight: 500;
    font-size: clamp(15px, 1.6vw, 20px);
    max-width: 34ch;
  }
  .c-title .sub b { font-weight: 700; }

  /* ===== Content sections ===== */
  main {
    display: grid;
    grid-template-columns: repeat(12, 1fr);
    gap: var(--line);
    background: var(--black);
    padding: var(--line);
  }
  section {
    background: var(--white);
    padding: clamp(24px, 4vw, 48px);
    grid-column: span 4;
  }
  section h2 {
    font-weight: 900;
    font-size: 13px;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin-bottom: 14px;
    padding-bottom: 10px;
    border-bottom: 4px solid var(--black);
  }
  section p { font-size: 16px; }
  section p + p { margin-top: 10px; }
  .s-painter  { grid-column: 1 / span 5; }
  .s-movement { grid-column: 6 / span 3; background: var(--yellow); }
  .s-movement h2 { border-color: var(--black); }
  .s-matters  { grid-column: 9 / span 4; }
  .s-matters  { background: var(--red); color: var(--white); }
  .s-matters h2 { border-color: var(--white); }
  .s-facts    { grid-column: 1 / span 12; }
  .s-facts dl {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 18px 32px;
    margin-top: 6px;
  }
  .s-facts dt {
    font-weight: 700;
    font-size: 12px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
  }
  .s-facts dd { font-size: 16px; margin-top: 2px; }

  /* ===== Footer / CTA ===== */
  footer {
    background: var(--black);
    color: var(--white);
    padding: clamp(32px, 6vw, 64px) clamp(24px, 5vw, 56px);
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
  }
  footer p { font-size: 16px; max-width: 48ch; }
  footer a.cta {
    display: inline-block;
    background: var(--yellow);
    color: var(--black);
    font-weight: 700;
    font-size: 15px;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    text-decoration: none;
